
-- Q1 tables
-- which FEC / 527 / charity / FTC / court tables exist, with row counts
SELECT TABLE_SCHEMA, TABLE_NAME, ROW_COUNT FROM LIBRARY_MARTS.INFORMATION_SCHEMA.TABLES
WHERE TABLE_NAME ILIKE ANY ('%FEC%','%527%','%FTC%','%CHARIT%','%990%','%BMF%','%PUB78%','%TELEMARK%','%DNC%','%OPEX%','%DISB%','%SOLICIT%')
ORDER BY 1,2

-- Q2 fec_disb_tables
-- any FEC disbursement / operating-expenditure / committee-to-committee table anywhere in the account (landing included)
SELECT TABLE_CATALOG, TABLE_SCHEMA, TABLE_NAME, ROW_COUNT FROM SNOWFLAKE.ACCOUNT_USAGE.TABLES
WHERE DELETED IS NULL AND TABLE_NAME ILIKE '%FEC%' AND (TABLE_NAME ILIKE ANY ('%OPPEXP%','%OPEXP%','%OPER%','%DISB%','%EXPEND%','%TO_COMMITTEE%','%ITOTH%','%ITPAS%','%SCHED%'))
ORDER BY ROW_COUNT DESC NULLS LAST

-- Q3 base19
-- the 19: per-group totals, copies across forms dropped (EIN+payee+date+amount, keep the largest single-form count)
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
f AS (SELECT b.EIN, UPPER(TRIM(REGEXP_REPLACE(RECIPIENT_NAME,'[^A-Za-z0-9& ]',''))) r, EXPENDITURE_DATE d, EXPENDITURE_AMOUNT a, FORM_ID_NUMBER, COUNT(*) n,
    MAX(IFF(REGEXP_LIKE(EXPENDITURE_PURPOSE, '.*(fundrais|telemarket|telefund|direct mail|solicit|caging|donor acqu|mail house|list rental|phone).*', 'i'),1,0)) fr,
    MAX(IFF(EXPENDITURE_PURPOSE ILIKE '%contribution%' OR EXPENDITURE_PURPOSE ILIKE '%donation%',1,0)) ct
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES b JOIN g ON g.EIN=b.EIN GROUP BY 1,2,3,4,5),
k AS (SELECT EIN, r, d, a, MAX(n) n, MAX(fr) fr, MAX(ct) ct FROM f GROUP BY 1,2,3,4),
o AS (SELECT b.EIN, MAX_BY(ORG_NAME, EXPENDITURE_DATE) org, COUNT(*) raw_rows, SUM(EXPENDITURE_AMOUNT) raw_amt FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES b JOIN g ON g.EIN=b.EIN GROUP BY 1)
SELECT k.EIN, o.org, MIN(YEAR(d)) y0, MAX(d) last_d, o.raw_rows, ROUND(o.raw_amt/1e6,2) raw_m, ROUND(SUM(n*a)/1e6,2) dedup_m,
  ROUND(100*SUM(IFF(fr=1,n*a,0))/SUM(n*a),1) pct_fr, ROUND(SUM(IFF(ct=1,n*a,0))/1e3,1) contrib_k,
  ROUND(SUM(IFF(r LIKE 'BF%TELECOM%',n*a,0))/1e6,2) bftel_m, MIN(IFF(r LIKE 'BF%TELECOM%',d,NULL)) bftel_first,
  ROUND(SUM(IFF(r LIKE 'RESIDENTIAL PROGRAMS%',n*a,0))/1e6,2) rpi_m
FROM k JOIN o USING (EIN) GROUP BY k.EIN, o.org, o.raw_rows, o.raw_amt ORDER BY dedup_m DESC

-- Q4 top_vendors19
-- top payees of the 19 (copies dropped), vendor name normalised (no punctuation, no spaces, no LLC/INC suffix), with payee city/state and purposes
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
f AS (SELECT b.EIN, REGEXP_REPLACE(REGEXP_REPLACE(UPPER(RECIPIENT_NAME),'[^A-Z0-9]',''),'(LLC|INC|CORP|CORPORATION|CO|LTD|LP)$','') v, EXPENDITURE_DATE d, EXPENDITURE_AMOUNT a, FORM_ID_NUMBER, COUNT(*) n,
   ANY_VALUE(UPPER(RECIPIENT_CITY)||' '||RECIPIENT_STATE) loc, ANY_VALUE(LEFT(UPPER(EXPENDITURE_PURPOSE),40)) p
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES b JOIN g ON g.EIN=b.EIN GROUP BY 1,2,3,4,5),
k AS (SELECT EIN, v, d, a, MAX(n) n, ANY_VALUE(loc) loc, ANY_VALUE(p) p FROM f GROUP BY 1,2,3,4)
SELECT v, ROUND(SUM(n*a)/1e6,2) amt_m, COUNT(DISTINCT EIN) groups19, MIN(d) first_d, MAX(d) last_d,
  LISTAGG(DISTINCT loc, ' / ') WITHIN GROUP (ORDER BY loc) locs, LEFT(LISTAGG(DISTINCT p, ' / '),200) purposes,
  ROUND(100*SUM(n*a)/SUM(SUM(n*a)) OVER (),1) pct_of_19
FROM k GROUP BY v ORDER BY amt_m DESC LIMIT 30

-- Q5 vendor_network
-- vendor network: every 527 (whole Schedule B) paying the 19's top vendors; second field = payee state must be one the 19 saw for that vendor. copies across forms dropped.
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
b AS (SELECT EIN, ORG_NAME, REGEXP_REPLACE(REGEXP_REPLACE(UPPER(RECIPIENT_NAME),'[^A-Z0-9]',''),'(LLC|INC|CORP|CORPORATION|CO|LTD|LP)$','') v, UPPER(TRIM(RECIPIENT_STATE)) st,
   EXPENDITURE_DATE d, EXPENDITURE_AMOUNT a, FORM_ID_NUMBER
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES),
vend AS (SELECT v, ARRAY_AGG(DISTINCT st) sts FROM b WHERE EIN IN (SELECT EIN FROM g) AND v IN ('RESIDENTIALPROGRAMS','BFTELECOM','CAMPAIGNCALLING','AMERICANLIBERTYGROUP','SIMPLEDATA','UNITEDSUPPORT','ONEVOICESOLUTIONS',
  'NORTHAMERICANFULFILLMENT','NORTHAMERICANFULFILMENT','POLITICALRESPONSE','GSI','PROSPEAKING','OPTICALMARKETING','PUBLICSUPPORTSERVICES','GRASSROOTSFUNDGROUP','POLITICALFUNDRAISINGGROUP','CAPITALVENDORMANAGEMENT',
  'POLITICALMARKETINGSERVICES','EMERGENTMARKETING','ACTIONCOMMITTEEMARKETING','UNIQTECHNOLOGIES','VENDORSYSTEMS','THEFUNDRAISINGGROUP','ADVANCEDCREATIVEMEDIA','GCI','CAMPAIGNMARKETING','AMERICANMARKETINGSERVICES') GROUP BY v),
f AS (SELECT b.EIN, b.v, b.d, b.a, b.FORM_ID_NUMBER, COUNT(*) n, ANY_VALUE(ORG_NAME) org FROM b JOIN vend ON vend.v=b.v AND ARRAY_CONTAINS(b.st::variant, vend.sts) GROUP BY 1,2,3,4,5),
k AS (SELECT EIN, v, d, a, MAX(n) n, ANY_VALUE(org) org FROM f GROUP BY 1,2,3,4)
SELECT EIN, MAX(org) org, IFF(EIN IN (SELECT EIN FROM g),'Y','N') in19, v, ROUND(SUM(n*a)/1e6,3) amt_m, MIN(d) first_d, MAX(d) last_d, COUNT(*) pay_rows
FROM k GROUP BY EIN, v ORDER BY in19, v, amt_m DESC

-- Q6 identity19
-- identity fields of the 19: custodian, contact, mailing and custodian address from 8872s; officers from 8871 officer list; related entities
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
r AS (SELECT * FROM LIBRARY_MARTS.POLITICS.POLITICS__IRS527_8872_REPORTS WHERE EIN IN (SELECT EIN FROM g))
SELECT EIN, 'custodian' k, UPPER(TRIM(CUSTODIAN_NAME)) v, UPPER(TRIM(CUSTODIAN_ADDR1))||', '||UPPER(TRIM(CUSTODIAN_CITY))||' '||CUSTODIAN_STATE x, COUNT(*) n, MIN(PERIOD_BEGIN_DATE)::string d0, MAX(PERIOD_END_DATE)::string d1 FROM r GROUP BY 1,2,3,4
UNION ALL SELECT EIN, 'contact', UPPER(TRIM(CONTACT_NAME)), UPPER(TRIM(CONTACT_ADDR1))||', '||UPPER(TRIM(CONTACT_CITY))||' '||CONTACT_STATE, COUNT(*), MIN(PERIOD_BEGIN_DATE)::string, MAX(PERIOD_END_DATE)::string FROM r GROUP BY 1,2,3,4
UNION ALL SELECT EIN, 'mail', UPPER(TRIM(MAILING_ADDR1)), UPPER(TRIM(MAILING_CITY))||' '||MAILING_STATE||' '||LEFT(MAILING_ZIP,5), COUNT(*), MIN(PERIOD_BEGIN_DATE)::string, MAX(PERIOD_END_DATE)::string FROM r GROUP BY 1,2,3,4
UNION ALL SELECT EIN, 'email', UPPER(TRIM(EMAIL_ADDRESS)), NULL, COUNT(*), NULL, NULL FROM r GROUP BY 1,2,3,4
UNION ALL SELECT EIN, 'officer', UPPER(TRIM(ENTITY_NAME)), ENTITY_TITLE, COUNT(*), NULL, NULL FROM LIBRARY_MARTS.POLITICS.POLITICS__IRS527_DIRECTORS_OFFICERS WHERE EIN IN (SELECT EIN FROM g) GROUP BY 1,2,3,4
UNION ALL SELECT EIN, 'related', UPPER(TRIM(ENTITY_NAME)), ENTITY_RELATIONSHIP||' | '||UPPER(COALESCE(ENTITY_CITY,''))||' '||COALESCE(ENTITY_STATE,''), COUNT(*), NULL, NULL FROM LIBRARY_MARTS.POLITICS.POLITICS__IRS527_RELATED_ENTITIES WHERE EIN IN (SELECT EIN FROM g) GROUP BY 1,2,3,4
UNION ALL SELECT EIN, 'org8871', UPPER(TRIM(ORGANIZATION_NAME)), LEFT(PURPOSE,150), COUNT(*), MIN(ESTABLISHED_DATE)::string, MAX(EXEMPT_8872_IND)||'/'||MAX(EXEMPT_990_IND) FROM LIBRARY_MARTS.POLITICS.POLITICS__IRS527_8871_ORGS WHERE EIN IN (SELECT EIN FROM g) GROUP BY 1,2,3,4
ORDER BY 1,2,5 DESC

-- Q7 fec_lookalikes
-- FEC committees tied to the 19: (a) look-alike name core, (b) treasurer surname from the 19's custodians/officers, (c) street address from the 19's 8872s. all three committee files unioned.
WITH c AS (
  SELECT CMTE_ID, CMTE_NM, TRES_NM, CMTE_ST1, CMTE_CITY, CMTE_ST, CMTE_ZIP, CMTE_TP, CMTE_DSGN, 'fin' src FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEES
  UNION ALL SELECT FEC_CMTE_ID, CMTE_NM, TRES_NM, CMTE_ST1, CMTE_CITY, CMTE_ST, CMTE_ZIP, CMTE_TP, CMTE_DSGN, 'bulk' FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_BULK_COMMITTEES
  UNION ALL SELECT CMTE_ID, CMTE_NM, TRES_NM, NULL, CMTE_CITY, CMTE_ST, CMTE_ZIP, CMTE_TP, CMTE_DSGN, 'pol'||CYCLE FROM LIBRARY_MARTS.POLITICS.POLITICS__FEC_COMMITTEE),
n AS (SELECT CMTE_ID, ANY_VALUE(CMTE_NM) nm, LISTAGG(DISTINCT UPPER(TRES_NM),' / ') tres, LISTAGG(DISTINCT UPPER(COALESCE(CMTE_ST1,''))||', '||UPPER(CMTE_CITY)||' '||CMTE_ST,' / ') addr,
   ANY_VALUE(CMTE_TP) tp, LISTAGG(DISTINCT src,',') srcs,
   ' '||REGEXP_REPLACE(UPPER(ANY_VALUE(CMTE_NM)),'[^A-Z0-9]+',' ')||' ' nn FROM c GROUP BY CMTE_ID),
cores AS (SELECT column1 core FROM VALUES ('AMERICAN POLICE OFFICERS ALLIANCE'),('FIREFIGHTERS AND EMS FUND'),('FIREFIGHTERS SUPPORT FUND'),('NATIONAL POLICE SUPPORT FUND'),('COMMITTEE FOR POLICE OFFICERS DEFENSE'),
  ('AMERICAN VETERANS HONOR FUND'),('AMERICAN BREAST CANCER COALITION'),('NATIONAL COMMITTEE FOR VOLUNTEER FIREFIGHTERS'),('NATIONAL COALITION FOR DISABLED VETERANS'),('VETERANS ACTION NETWORK'),
  ('VETERANS IN DEFENSE OF LIBERTY'),('NATIONAL CANCER ALLIANCE'),('POSC'),('AMERICAN COALITION FOR POLICE'),('UNITED FIREFIGHTERS SUPPORT'),('AMERICAN ALLIANCE FOR MILITARY VETERANS'),('AVSC'),('VF2024'),
  ('NATIONAL POLICE SHERIFFS COALITION'),('UNITED HEALTH PAC'),('AMERICAN ALLIANCE FOR PUBLIC SAFETY'),('CONSTITUTIONAL POLICING SUPPORT'),('POLICE OFFICERS DEFENSE ALLIANCE'),('REAL DEMOCRACY FUND'),('AMCC PAC'),('UCVF PAC'),('CANCER RECOVERY ACTION')),
sur AS (SELECT column1 s FROM VALUES ('SKYLES'),('STUEBS'),('STEUBS'),('QUAYE'),('PORTER, NILE'),('PORTER, JANE'),('LAMERS'),('EYLER'),('FORSYTHE'),('GREENLEE'),('GRAGERT'),('PULCIANI'),('PULSIANI'),('NIZICK'),
  ('CURRAN, DAN'),('MAGILL'),('GUTMANN'),('MAICHLE'),('FRANKOVIS'),('MAJCEN'),('FOTIS'),('SECHER'),('HOWELL, JAMES'),('PHILLIPS, MARK'),('DAVIS, BILL'),('DAVIS, WILLIAM'),('DAVIS, DAVID'),('JOHNS, KYLE'),('MEYER, RYAN'),('LEWIS, SIMON')),
adr AS (SELECT column1 a FROM VALUES ('2301 SUN VALLEY'),('200 S EXECUTIVE'),('14497 POTOMAC MILLS'),('9480 MAIN ST'),('5801 LEESBURG PIKE'),('1104 W'),('110 COLISEUM'),('1 EAST ERIE'),('1 E ERIE'),('2000 COLORADO BLVD'),
  ('1 WASHINGTON MALL'),('900 COMMONWEALTH'),('10521 JUDICIAL'),('4250 FAIRFAX'),('5680 KING CENTRE'),('1101 WILSON'),('1655 FORT MYER'),('2800 EISENHOWER'),('301 S MCDOWELL'),('4301 50TH'),('4210 ELECTRIC'),
  ('7345 W'),('3804 WILSON'),('7400 BEAUMONT'),('4650 S'),('177 HUNTINGTON'),('3540 TORINGDON'),('2010 CORPORATE RIDGE'),('2331 MILL'))
SELECT n.CMTE_ID, n.nm, n.tp, n.tres, n.addr, n.srcs,
  (SELECT LISTAGG(core,'|') FROM cores WHERE n.nn LIKE '% '||core||' %') name_hit,
  (SELECT LISTAGG(s,'|') FROM sur WHERE n.tres LIKE '%'||s||'%') tres_hit,
  (SELECT LISTAGG(a,'|') FROM adr WHERE n.addr LIKE '%'||a||'%') addr_hit
FROM n
WHERE EXISTS (SELECT 1 FROM cores WHERE n.nn LIKE '% '||core||' %')
   OR (EXISTS (SELECT 1 FROM sur WHERE n.tres LIKE '%'||s||'%') AND REGEXP_LIKE(n.nn,'.*(POLICE|SHERIFF|FIRE|VETERAN|CANCER|HEALTH|MILITARY|TROOPER|LAW ENFORCEMENT|FIRST RESPONDER|SAFETY|DISABLED|BREAST).*'))
   OR EXISTS (SELECT 1 FROM adr WHERE n.addr LIKE '%'||a||'%' AND REGEXP_LIKE(n.nn,'.*(POLICE|SHERIFF|FIRE|VETERAN|CANCER|HEALTH|MILITARY|TROOPER|LAW ENFORCEMENT|FIRST RESPONDER|SAFETY|DISABLED|BREAST).*'))
ORDER BY n.nm

-- Q8 fec_pac_summary
-- FEC money for the look-alike / shared-treasurer committees: per-cycle totals, and how much reached candidates or other committees
SELECT CMTE_ID, COMMITTEE_NAME, COVERAGE_END_DATE, TOTAL_RECEIPTS, INDIVIDUAL_CONTRIBUTIONS, TOTAL_DISBURSEMENTS, CONTRIBUTIONS_TO_OTHER_COMMITTEES, INDEPENDENT_EXPENDITURES, PCT_DISBURSED_TO_OTHERS, CASH_CLOSE_OF_PERIOD, DEBTS_OWED_BY
FROM LIBRARY_MARTS.POLITICS.POLITICS__FED_FEC_PAC_SUMMARY
WHERE CMTE_ID IN ('C00822106','C00691329','C00469239','C00691949','C00784496','C00715573','C00667865','C00763979','C00669051','C00674267')
ORDER BY CMTE_ID, COVERAGE_END_DATE

-- Q9 bmf_links
-- IRS exempt-org master file: are the 19 (by EIN) or their named affiliates / look-alikes (by name) or their street addresses registered tax-exempt orgs?
WITH b AS (SELECT EIN, ORG_NAME, IN_CARE_OF, STREET, CITY, STATE, SUBSECTION_CODE, NTEE_CODE, RULING_DATE, REVENUE_AMT, ASSET_AMT, TAX_PERIOD_YYYYMM, FOUNDATION_CODE,
   ' '||REGEXP_REPLACE(UPPER(ORG_NAME),'[^A-Z0-9]+',' ')||' ' nn, UPPER(STREET) st FROM LIBRARY_MARTS.CORPORATE_REGISTRY.CORPORATE_REGISTRY__FED_IRS_EO_BMF),
cores AS (SELECT column1 core FROM VALUES ('AMERICAN POLICE OFFICERS ALLIANCE'),('FIREFIGHTERS AND EMS FUND'),('FIREFIGHTERS SUPPORT FUND'),('NATIONAL POLICE SUPPORT FUND'),('COMMITTEE FOR POLICE OFFICERS DEFENSE'),
  ('AMERICAN VETERANS HONOR FUND'),('AMERICAN BREAST CANCER COALITION'),('NATIONAL COMMITTEE FOR VOLUNTEER FIREFIGHTERS'),('NATIONAL COALITION FOR DISABLED VETERANS'),('VETERANS ACTION NETWORK'),
  ('VETERANS IN DEFENSE OF LIBERTY'),('NATIONAL CANCER ALLIANCE'),('AMERICAN COALITION FOR POLICE'),('UNITED FIREFIGHTERS SUPPORT'),('AMERICAN ALLIANCE FOR MILITARY VETERANS'),
  ('NATIONAL POLICE SHERIFFS COALITION'),('AMERICAN ALLIANCE FOR PUBLIC SAFETY'),('CONSTITUTIONAL POLICING SUPPORT'),('POLICE OFFICERS DEFENSE ALLIANCE'),('POLICE OFFICERS DEFENSE'),('REAL DEMOCRACY FUND'),('CANCER RECOVERY ACTION'),('FIREFIGHTERS SUPPORT ASSOCIATION'),('AMERICAN WOUNDED VETERANS'),('VOLUNTEER FIREFIGHTER PARAMEDIC')),
adr AS (SELECT column1 a FROM VALUES ('2301 SUN VALLEY'),('200 S EXECUTIVE'),('14497 POTOMAC MILLS'),('9480 MAIN ST'),('5801 LEESBURG PIKE'),('110 COLISEUM'),('1 E ERIE'),('1 EAST ERIE'),('2000 COLORADO BLVD'),
  ('1 WASHINGTON MALL'),('900 COMMONWEALTH'),('10521 JUDICIAL'),('4250 FAIRFAX'),('5680 KING CENTRE'),('1101 WILSON'),('1655 FORT MYER'),('2800 EISENHOWER'),('301 S MCDOWELL'),('4301 50TH'),('4210 ELECTRIC'),
  ('7345 W 100TH'),('3804 WILSON'),('7400 BEAUMONT'),('1104 W BROAD'),('1104 WEST BROAD'))
SELECT b.EIN, b.ORG_NAME, b.IN_CARE_OF, b.STREET, b.CITY, b.STATE, b.SUBSECTION_CODE, b.NTEE_CODE, b.RULING_DATE, b.REVENUE_AMT, b.TAX_PERIOD_YYYYMM,
  IFF(b.EIN IN ('821194581','822366231','815214552','843153271','822315009','834686848','843763411','853307234','472041040','273594732','843763242','921706849','922354897','861386683','843763606','922452599','923489519','854325630','923489713'),'EIN','') ein_hit,
  (SELECT LISTAGG(core,'|') FROM cores WHERE b.nn LIKE '% '||core||' %') name_hit,
  (SELECT LISTAGG(a,'|') FROM adr WHERE b.st LIKE a||'%') addr_hit
FROM b
WHERE b.EIN IN ('821194581','822366231','815214552','843153271','822315009','834686848','843763411','853307234','472041040','273594732','843763242','921706849','922354897','861386683','843763606','922452599','923489519','854325630','923489713')
  OR EXISTS (SELECT 1 FROM cores WHERE b.nn LIKE '% '||core||' %')
  OR (EXISTS (SELECT 1 FROM adr WHERE b.st LIKE a||'%') AND REGEXP_LIKE(b.nn,'.*(POLICE|SHERIFF|FIRE|VETERAN|CANCER|MILITARY|TROOPER|LAW ENFORCEMENT|RESPONDER|PUBLIC SAFETY|DISABLED|BREAST).*'))
ORDER BY b.ORG_NAME

-- Q10 schedA19
-- Schedule A (money in) for the 19: itemized donors, copies across forms and lump rows dropped; donor = name + 5-digit zip; how many donors give to several of the 19
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
a AS (SELECT s.EIN, REGEXP_REPLACE(UPPER(CONTRIBUTOR_NAME),'[^A-Z ]','') nm, LEFT(CONTRIBUTOR_ZIP,5) z, CONTRIBUTION_DATE d, CONTRIBUTION_AMOUNT amt, FORM_ID_NUMBER, COUNT(*) n,
   MAX(IFF(UPPER(CONTRIBUTOR_OCCUPATION) LIKE 'RETIRED%',1,0)) ret
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_A_CONTRIBUTIONS s JOIN g ON g.EIN=s.EIN
  WHERE NOT REGEXP_LIKE(UPPER(CONTRIBUTOR_NAME),'.*(AGGREGATE|UNITEMIZED|TOTAL|BELOW THRESHOLD|VARIOUS|NON-ITEMIZED|NONITEMIZED|WITHHELD).*')
  GROUP BY 1,2,3,4,5,6),
k AS (SELECT EIN, nm, z, d, amt, MAX(n) n, MAX(ret) ret FROM a GROUP BY 1,2,3,4,5),
dn AS (SELECT nm, z, COUNT(DISTINCT EIN) groups, SUM(n*amt) tot, SUM(n) gifts, MAX(ret) ret FROM k GROUP BY 1,2)
SELECT 'all' k, NULL grp, COUNT(*) donors, SUM(gifts) gifts, ROUND(SUM(tot)/1e6,2) tot_m, ROUND(MEDIAN(tot),0) med_per_donor, ROUND(100*AVG(ret),1) pct_retired,
  SUM(IFF(groups>=2,1,0)) donors_2plus, SUM(IFF(groups>=5,1,0)) donors_5plus, MAX(groups) max_groups, ROUND(SUM(IFF(groups>=2,tot,0))/1e6,2) tot_2plus_m
FROM dn
UNION ALL
SELECT 'grp', EIN, COUNT(DISTINCT nm||z), SUM(n), ROUND(SUM(n*amt)/1e6,2), ROUND(MEDIAN(amt),0), ROUND(100*AVG(ret),1), NULL, NULL, NULL, NULL FROM k GROUP BY EIN
ORDER BY k, tot_m DESC

-- Q11 donors_in_fec
-- donors of the 19 (Schedule A, lump rows dropped) found in FEC individual contributions: key = 5-digit zip + surname + first initial. which FEC committees do they give to?
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
s AS (SELECT DISTINCT LEFT(CONTRIBUTOR_ZIP,5) z,
   IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',1)), REGEXP_SUBSTR(TRIM(UPPER(CONTRIBUTOR_NAME)),'[A-Z\-\']+$')) ln,
   LEFT(IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',2)), TRIM(UPPER(CONTRIBUTOR_NAME))),1) fi
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_A_CONTRIBUTIONS WHERE EIN IN (SELECT EIN FROM g)
   AND NOT REGEXP_LIKE(UPPER(CONTRIBUTOR_NAME),'.*(AGGREGATE|UNITEMIZED|TOTAL|BELOW THRESHOLD|VARIOUS|ITEMIZED|WITHHELD).*')),
f AS (SELECT CMTE_ID, LEFT(ZIP_CODE,5) z, TRIM(SPLIT_PART(DONOR_NAME,',',1)) ln, LEFT(TRIM(SPLIT_PART(DONOR_NAME,',',2)),1) fi, TRANSACTION_AMT a
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_INDIV_CONTRIBUTIONS WHERE COALESCE(MEMO_CD,'')<>'X' AND LEFT(ZIP_CODE,5) IN (SELECT z FROM s)),
m AS (SELECT f.* FROM f JOIN s ON s.z=f.z AND s.ln=f.ln AND s.fi=f.fi)
SELECT 'summary' k, NULL CMTE_ID, (SELECT COUNT(*) FROM s) keys_19, COUNT(DISTINCT z||ln||fi) matched_keys, COUNT(*) fec_rows, ROUND(SUM(a)/1e6,2) fec_m, NULL nm FROM m
UNION ALL
SELECT * FROM (SELECT 'cmte', m.CMTE_ID, NULL, COUNT(DISTINCT z||ln||fi), COUNT(*), ROUND(SUM(a)/1e6,3), MAX(d.CMTE_NM)
  FROM m LEFT JOIN LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEES d ON d.CMTE_ID=m.CMTE_ID GROUP BY m.CMTE_ID ORDER BY 4 DESC LIMIT 45)
ORDER BY k DESC, matched_keys DESC

-- Q12 donors_in_fec
-- rerun of Q11 (regex fixed)
-- donors of the 19 (Schedule A, lump rows dropped) found in FEC individual contributions: key = 5-digit zip + surname + first initial. which FEC committees do they give to?
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
s AS (SELECT DISTINCT LEFT(CONTRIBUTOR_ZIP,5) z,
   IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',1)), REGEXP_SUBSTR(TRIM(UPPER(CONTRIBUTOR_NAME)),'[A-Z\-\']+$')) ln,
   LEFT(IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',2)), TRIM(UPPER(CONTRIBUTOR_NAME))),1) fi
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_A_CONTRIBUTIONS WHERE EIN IN (SELECT EIN FROM g)
   AND NOT REGEXP_LIKE(UPPER(CONTRIBUTOR_NAME),'.*(AGGREGATE|UNITEMIZED|TOTAL|BELOW THRESHOLD|VARIOUS|ITEMIZED|WITHHELD).*')),
f AS (SELECT CMTE_ID, LEFT(ZIP_CODE,5) z, TRIM(SPLIT_PART(DONOR_NAME,',',1)) ln, LEFT(TRIM(SPLIT_PART(DONOR_NAME,',',2)),1) fi, TRANSACTION_AMT a
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_INDIV_CONTRIBUTIONS WHERE COALESCE(MEMO_CD,'')<>'X' AND LEFT(ZIP_CODE,5) IN (SELECT z FROM s)),
m AS (SELECT f.* FROM f JOIN s ON s.z=f.z AND s.ln=f.ln AND s.fi=f.fi)
SELECT 'summary' k, NULL CMTE_ID, (SELECT COUNT(*) FROM s) keys_19, COUNT(DISTINCT z||ln||fi) matched_keys, COUNT(*) fec_rows, ROUND(SUM(a)/1e6,2) fec_m, NULL nm FROM m
UNION ALL
SELECT * FROM (SELECT 'cmte', m.CMTE_ID, NULL, COUNT(DISTINCT z||ln||fi), COUNT(*), ROUND(SUM(a)/1e6,3), MAX(d.CMTE_NM)
  FROM m LEFT JOIN LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEES d ON d.CMTE_ID=m.CMTE_ID GROUP BY m.CMTE_ID ORDER BY 4 DESC LIMIT 45)
ORDER BY k DESC, matched_keys DESC

