-- Q14 lesa_overlap
-- the police-named FEC PAC that shares 1,421 donors with the 19, plus three other niche PACs in the top 45: who runs them, how big is their donor list, what share overlaps the 19
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
s AS (SELECT DISTINCT LEFT(CONTRIBUTOR_ZIP,5) z,
   IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',1)), REGEXP_SUBSTR(TRIM(UPPER(CONTRIBUTOR_NAME)),'[A-Z]+$')) ln,
   LEFT(IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',2)), TRIM(UPPER(CONTRIBUTOR_NAME))),1) fi
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_A_CONTRIBUTIONS WHERE EIN IN (SELECT EIN FROM g)
   AND NOT REGEXP_LIKE(UPPER(CONTRIBUTOR_NAME),'.*(AGGREGATE|UNITEMIZED|TOTAL|BELOW THRESHOLD|VARIOUS|ITEMIZED|WITHHELD).*')),
f AS (SELECT CMTE_ID, LEFT(ZIP_CODE,5)||TRIM(SPLIT_PART(DONOR_NAME,',',1))||LEFT(TRIM(SPLIT_PART(DONOR_NAME,',',2)),1) kk, TRANSACTION_AMT a, TRANSACTION_DATE d
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_INDIV_CONTRIBUTIONS WHERE COALESCE(MEMO_CD,'')<>'X' AND CMTE_ID IN ('C00681825','C00570416','C00570226','C00573519','C00003418')),
t AS (SELECT CMTE_ID, COUNT(DISTINCT kk) donors, COUNT(DISTINCT IFF(kk IN (SELECT z||ln||fi FROM s), kk, NULL)) donors_in19, ROUND(SUM(a)/1e6,2) amt_m, MIN(d) d0, MAX(d) d1 FROM f GROUP BY 1),
c AS (SELECT CMTE_ID, ANY_VALUE(CMTE_NM) nm, LISTAGG(DISTINCT TRES_NM,' / ') tres, LISTAGG(DISTINCT CMTE_ST1||', '||CMTE_CITY||' '||CMTE_ST,' / ') addr, ANY_VALUE(CMTE_TP) tp
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEES WHERE CMTE_ID IN ('C00681825','C00570416','C00570226','C00573519','C00003418') GROUP BY 1),
p AS (SELECT CMTE_ID, ROUND(SUM(TOTAL_RECEIPTS)/1e6,2) rec_m, ROUND(SUM(TOTAL_DISBURSEMENTS)/1e6,2) dis_m, ROUND(SUM(CONTRIBUTIONS_TO_OTHER_COMMITTEES)/1e6,3) to_cmtes_m, ROUND(SUM(INDEPENDENT_EXPENDITURES)/1e6,3) ie_m,
   LISTAGG(DISTINCT YEAR(COVERAGE_END_DATE)::string, ',') yrs
  FROM LIBRARY_MARTS.POLITICS.POLITICS__FED_FEC_PAC_SUMMARY WHERE CMTE_ID IN ('C00681825','C00570416','C00570226','C00573519','C00003418') GROUP BY 1)
SELECT t.*, ROUND(100*donors_in19/donors,1) pct_in19, c.nm, c.tp, c.tres, c.addr, p.rec_m, p.dis_m, p.to_cmtes_m, p.ie_m, p.yrs
FROM t LEFT JOIN c USING (CMTE_ID) LEFT JOIN p USING (CMTE_ID) ORDER BY pct_in19 DESC

-- Q15 pac_overlap_rank
-- systematic: every non-party PAC (FEC type O,Q,N,V,W,U) with 100+ of the 19's donors; share of its whole itemized donor list that also gave to the 19. 
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
s AS (SELECT DISTINCT LEFT(CONTRIBUTOR_ZIP,5)||IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',1)), REGEXP_SUBSTR(TRIM(UPPER(CONTRIBUTOR_NAME)),'[A-Z]+$'))
   ||LEFT(IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',2)), TRIM(UPPER(CONTRIBUTOR_NAME))),1) kk
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_A_CONTRIBUTIONS WHERE EIN IN (SELECT EIN FROM g)
   AND NOT REGEXP_LIKE(UPPER(CONTRIBUTOR_NAME),'.*(AGGREGATE|UNITEMIZED|TOTAL|BELOW THRESHOLD|VARIOUS|ITEMIZED|WITHHELD).*')),
c AS (SELECT CMTE_ID, ANY_VALUE(CMTE_NM) nm, ANY_VALUE(CMTE_TP) tp, ANY_VALUE(TRES_NM) tres, ANY_VALUE(CMTE_CITY||' '||CMTE_ST) city FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_COMMITTEES GROUP BY 1),
f AS (SELECT i.CMTE_ID, LEFT(ZIP_CODE,5)||TRIM(SPLIT_PART(DONOR_NAME,',',1))||LEFT(TRIM(SPLIT_PART(DONOR_NAME,',',2)),1) kk
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_INDIV_CONTRIBUTIONS i JOIN c ON c.CMTE_ID=i.CMTE_ID AND c.tp IN ('O','Q','N','V','W','U')
  WHERE COALESCE(MEMO_CD,'')<>'X'),
t AS (SELECT CMTE_ID, COUNT(DISTINCT kk) donors, COUNT(DISTINCT IFF(kk IN (SELECT kk FROM s), kk, NULL)) d19 FROM f GROUP BY 1)
SELECT t.*, ROUND(100*d19/donors,1) pct_in19, c.nm, c.tp, c.tres, c.city FROM t JOIN c USING (CMTE_ID) WHERE d19 >= 100 ORDER BY pct_in19 DESC LIMIT 40

-- Q16 fec_twin_money
-- FEC money for the 13 PACs whose donor lists overlap the 19 by 15%+ (plus the name/treasurer look-alikes): raised, spent, sent to candidates/committees, independent expenditures
SELECT CMTE_ID, MAX(COMMITTEE_NAME) nm, MIN(YEAR(COVERAGE_END_DATE)) y0, MAX(YEAR(COVERAGE_END_DATE)) y1, ROUND(SUM(TOTAL_RECEIPTS)/1e6,3) rec_m, ROUND(SUM(TOTAL_DISBURSEMENTS)/1e6,3) dis_m,
  ROUND(SUM(CONTRIBUTIONS_TO_OTHER_COMMITTEES)/1e6,3) to_cmtes_m, ROUND(SUM(INDEPENDENT_EXPENDITURES)/1e6,3) ie_m,
  ROUND(100*(SUM(CONTRIBUTIONS_TO_OTHER_COMMITTEES)+SUM(INDEPENDENT_EXPENDITURES))/NULLIF(SUM(TOTAL_DISBURSEMENTS),0),1) pct_to_politics, COUNT(*) cycles_rows
FROM LIBRARY_MARTS.POLITICS.POLITICS__FED_FEC_PAC_SUMMARY
WHERE CMTE_ID IN ('C00570093','C00715433','C00709113','C00710160','C00650168','C00784496','C00755694','C00681825','C00570416','C00758938','C00712885','C00710178','C00699801',
  'C00822106','C00667865','C00691329','C00691949','C00674267','C00715573')
GROUP BY CMTE_ID ORDER BY rec_m DESC

-- Q17 enforcement
-- the vendors, groups and FEC twins in FTC cases, CFPB complaints, CourtListener dockets and FJC civil cases (name patterns, multi-word only)
WITH p AS (SELECT column1 pat FROM VALUES ('%BF TELECOM%'),('%BF-TELECOM%'),('%BFTELECOM%'),('%RESIDENTIAL PROGRAMS%'),('%CAMPAIGN CALLING%'),('%ONE VOICE SOLUTIONS%'),('%POLITICAL RESPONSE LLC%'),
  ('%OPTICAL MARKETING%'),('%PUBLIC SUPPORT SERVICES%'),('%GRASSROOTS FUND GROUP%'),('%NORTH AMERICAN FULFILLMENT%'),('%PROSPEAKING%'),('%CAPITAL VENDOR MANAGEMENT%'),('%ACTION COMMITTEE MARKETING%'),
  ('%UNIQ TECHNOLOGIES%'),('%VENDOR SYSTEMS LLC%'),('%SIMPLE DATA LLC%'),('%AMERICAN LIBERTY GROUP%'),('%ADVANCED CREATIVE MEDIA%'),('%EMERGENT MARKETING%'),
  ('%POLICE OFFICERS ALLIANCE%'),('%NATIONAL POLICE SUPPORT FUND%'),('%FIREFIGHTERS SUPPORT FUND%'),('%POLICE OFFICERS DEFENSE%'),('%VETERANS HONOR FUND%'),('%BREAST CANCER COALITION%'),
  ('%VOLUNTEER FIREFIGHTERS%'),('%DISABLED VETERANS PAC%'),('%NATIONAL CANCER ALLIANCE%'),('%LAW ENFORCEMENT FOR A SAFER AMERICA%'),('%HONORING AMERICAN LAW ENFORCEMENT%'),('%COALITION FOR AMERICAN VETERANS%'),
  ('%CRISIS RELIEF PAC%'),('%DISABLED CHILDREN PAC%'),('%POLICE COALITION OF AMERICA%'),('%DATWYLER%'),('%PLISHKA%'),('%AMERICAN WOUNDED VETERANS%'))
SELECT 'ftc' src, ACTION_NAME nm, DATE_FILED::string d, DOCUMENT_URL x FROM LIBRARY_MARTS.JUSTICE.JUSTICE__FED_FTC_DATASETS WHERE UPPER(ACTION_NAME) LIKE ANY (SELECT pat FROM p)
UNION ALL SELECT 'cfpb', COMPANY, MIN(DATE_RECEIVED)::string, COUNT(*)::string FROM LIBRARY_MARTS.CONSUMER_PROTECTION.CONSUMER_PROTECTION__FED_CFPB_COMPLAINTS WHERE UPPER(COMPANY) LIKE ANY (SELECT pat FROM p) GROUP BY COMPANY
UNION ALL SELECT 'courtlistener', CASE_NAME, DATE_FILED::string, COURT_ID||' '||DOCKET_NUMBER||' nos='||COALESCE(NATURE_OF_SUIT,'') FROM LIBRARY_MARTS.JUSTICE.JUSTICE__FED_COURTLISTENER_DOCKETS WHERE UPPER(CASE_NAME) LIKE ANY (SELECT pat FROM p)
UNION ALL SELECT 'fjc_civil', PLAINTIFF||' v. '||DEFENDANT, FILE_DATE::string, DISTRICT||' '||DOCKET||' nos='||NATURE_OF_SUIT||' disp='||COALESCE(DISPOSITION::string,'') FROM LIBRARY_MARTS.JUSTICE.JUSTICE__FED_FJC_IDB_CIVIL
  WHERE UPPER(PLAINTIFF) LIKE ANY (SELECT pat FROM p) OR UPPER(DEFENDANT) LIKE ANY (SELECT pat FROM p)
ORDER BY 1,3

-- Q18 tcpa_outcomes
-- outcomes of the 8 robocall (TCPA) suits: FJC civil rows on docket number + filing date (second field), newest tape per case
SELECT DISTRICT, OFFICE, DOCKET, FILE_DATE, NATURE_OF_SUIT, PLAINTIFF, DEFENDANT, CLASS_ACTION, TERM_DATE, DISPOSITION, JUDGMENT, NATURE_OF_JUDGMENT, AMOUNT_RECEIVED, AMOUNT_DEMANDED, TAPE_YEAR
FROM LIBRARY_MARTS.JUSTICE.JUSTICE__FED_FJC_IDB_CIVIL
WHERE (DOCKET, FILE_DATE::date) IN (('2302890','2023-08-07'),('2600581','2026-01-19'),('2404679','2024-09-05'),('2610220','2026-01-20'),('2000438','2020-10-09'),('2102205','2021-08-18'),('2306316','2023-12-06'),('2500341','2025-08-26'))
QUALIFY ROW_NUMBER() OVER (PARTITION BY DISTRICT, DOCKET ORDER BY TAPE_YEAR DESC) = 1
ORDER BY FILE_DATE

-- Q19 network527
-- every 527 in the vendor network (the 19 + the 11 outside payers found in Q5): total spend, share paid to the 26 network vendors, fundraising share, candidate-contribution dollars. copies dropped.
WITH e AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713'),
  ('332084267'),('331888439'),('823288532'),('821820836'),('843288627'),('852675458'),('854065970'),('862042355'),('832868668'),('831616914')),
f AS (SELECT b.EIN, REGEXP_REPLACE(REGEXP_REPLACE(UPPER(RECIPIENT_NAME),'[^A-Z0-9]',''),'(LLC|INC|CORP|CORPORATION|CO|LTD|LP)$','') v, EXPENDITURE_DATE d, EXPENDITURE_AMOUNT a, FORM_ID_NUMBER, COUNT(*) n,
    MAX(IFF(REGEXP_LIKE(EXPENDITURE_PURPOSE, '.*(fundrais|telemarket|telefund|direct mail|solicit|caging|donor acqu|mail house|list rental|phone).*', 'i'),1,0)) fr,
    MAX(IFF(EXPENDITURE_PURPOSE ILIKE '%contribution%' OR EXPENDITURE_PURPOSE ILIKE '%donation%',1,0)) ct
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES b JOIN e ON e.EIN=b.EIN GROUP BY 1,2,3,4,5),
k AS (SELECT EIN, v, d, a, MAX(n) n, MAX(fr) fr, MAX(ct) ct FROM f GROUP BY 1,2,3,4),
o AS (SELECT EIN, MAX_BY(ORG_NAME, EXPENDITURE_DATE) org FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES WHERE EIN IN (SELECT EIN FROM e) GROUP BY 1)
SELECT k.EIN, o.org, MIN(YEAR(d)) y0, MAX(YEAR(d)) y1, ROUND(SUM(n*a)/1e6,3) tot_m,
  ROUND(100*SUM(IFF(v IN ('RESIDENTIALPROGRAMS','BFTELECOM','CAMPAIGNCALLING','SIMPLEDATA','UNITEDSUPPORT','ONEVOICESOLUTIONS','NORTHAMERICANFULFILLMENT','NORTHAMERICANFULFILMENT','POLITICALRESPONSE','GSI','PROSPEAKING',
   'OPTICALMARKETING','PUBLICSUPPORTSERVICES','GRASSROOTSFUNDGROUP','POLITICALFUNDRAISINGGROUP','CAPITALVENDORMANAGEMENT','POLITICALMARKETINGSERVICES','EMERGENTMARKETING','ACTIONCOMMITTEEMARKETING','UNIQTECHNOLOGIES',
   'VENDORSYSTEMS','THEFUNDRAISINGGROUP','ADVANCEDCREATIVEMEDIA','GCI','CAMPAIGNMARKETING','AMERICANMARKETINGSERVICES'),n*a,0))/SUM(n*a),1) pct_network_vendors,
  ROUND(100*SUM(IFF(fr=1,n*a,0))/SUM(n*a),1) pct_fr, ROUND(SUM(IFF(ct=1,n*a,0))/1e3,1) contrib_k
FROM k JOIN o USING (EIN) GROUP BY k.EIN, o.org ORDER BY tot_m DESC

-- Q20 peer_band
-- peer group: every 527 with $1M+ spending 2014 on (copies dropped). how many sit at 89.5-91.0% fundraising, and where do the rest fall?
WITH f AS (SELECT EIN, UPPER(TRIM(REGEXP_REPLACE(RECIPIENT_NAME,'[^A-Za-z0-9& ]',''))) r, EXPENDITURE_DATE d, EXPENDITURE_AMOUNT a, FORM_ID_NUMBER, COUNT(*) n,
    MAX(IFF(REGEXP_LIKE(EXPENDITURE_PURPOSE, '.*(fundrais|telemarket|telefund|direct mail|solicit|caging|donor acqu|mail house|list rental|phone).*', 'i'),1,0)) fr,
    MAX(IFF(EXPENDITURE_PURPOSE ILIKE '%contribution%' OR EXPENDITURE_PURPOSE ILIKE '%donation%',1,0)) ct
   FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES WHERE EXPENDITURE_DATE >= '2014-01-01' GROUP BY 1,2,3,4,5),
k AS (SELECT EIN, r, d, a, MAX(n) n, MAX(fr) fr, MAX(ct) ct FROM f GROUP BY 1,2,3,4),
e AS (SELECT EIN, SUM(n*a) tot, SUM(IFF(fr=1,n*a,0))/SUM(n*a) pfr, SUM(IFF(ct=1,n*a,0))/SUM(n*a) pct FROM k GROUP BY 1 HAVING SUM(n*a) >= 1e6),
o AS (SELECT EIN, MAX_BY(ORG_NAME, EXPENDITURE_DATE) org FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES GROUP BY 1)
SELECT 'bucket' k, CASE WHEN pfr >= 0.895 AND pfr < 0.91 THEN '89.5-91.0' WHEN pfr >= 0.5 THEN '50+ other' WHEN pfr >= 0.2 THEN '20-50' ELSE 'under 20' END b,
  COUNT(*) groups, ROUND(SUM(tot)/1e6,1) tot_m, ROUND(MEDIAN(pfr)*100,1) med_pfr, ROUND(MEDIAN(pct)*100,1) med_pct_contrib, NULL org
FROM e GROUP BY 1,2
UNION ALL SELECT 'all', 'all', COUNT(*), ROUND(SUM(tot)/1e6,1), ROUND(MEDIAN(pfr)*100,1), ROUND(MEDIAN(pct)*100,1), NULL FROM e
UNION ALL SELECT 'in_band', e.EIN, NULL, ROUND(tot/1e6,2), ROUND(pfr*100,1), ROUND(pct*100,1), o.org FROM e JOIN o USING (EIN) WHERE pfr >= 0.895 AND pfr < 0.91
ORDER BY 1, 4 DESC

-- Q21 lumps19
-- lump / withheld rows inside the 19: on the same form, how much is itemized besides the lump, and what did the 8872 say the Schedule B total was?
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
b AS (SELECT s.EIN, s.ORG_NAME, s.FORM_ID_NUMBER, UPPER(s.RECIPIENT_NAME) r, s.EXPENDITURE_AMOUNT a,
   IFF(REGEXP_LIKE(UPPER(RECIPIENT_NAME),'.*(WITHHELD|WITHHHELD|WITTHELD|WIITHELD|DISBURSEMENTS FROM|EXPENDITURES IN PERIOD|NON-DISCLOSED|AGGREGATE|TOTAL).*'),1,0) lump
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES s JOIN g ON g.EIN=s.EIN),
fm AS (SELECT FORM_ID_NUMBER, MAX(EIN) EIN, MAX(ORG_NAME) org, SUM(IFF(lump=1,a,0)) lump_amt, SUM(IFF(lump=0,a,0)) item_amt, COUNT_IF(lump=0) item_rows, MAX(IFF(lump=1,LEFT(r,45),NULL)) lump_name
  FROM b GROUP BY 1 HAVING SUM(lump) > 0)
SELECT fm.*, r.TOTAL_SCHED_B, r.PERIOD_BEGIN_DATE, r.PERIOD_END_DATE, r.AMENDED_REPORT_IND
FROM fm LEFT JOIN LIBRARY_MARTS.POLITICS.POLITICS__IRS527_8872_REPORTS r ON r.FORM_ID_NUMBER = fm.FORM_ID_NUMBER
ORDER BY lump_amt DESC LIMIT 30

-- Q22 people_hop
-- reverse hop: FEC treasurers of the donor-overlap PACs, and the 19's custodians, as custodians/contacts/officers of ANY 527 (distinctive surnames + first name)
WITH nm AS (SELECT column1 pat FROM VALUES ('%PLISHKA%'),('%DATWYLER%'),('RICHARD%LEAGUE%'),('%KEVITT%'),('BOB%STITT%'),('ROBERT%STITT%'),('%STEFANIDES%'),('%CAPPLEMAN%'),('%MCGRAIN%'),('MELODIE%JOHNSON%'),
  ('%PULCIANI%'),('%PULSIANI%'),('%NIZICK%'),('MATTHEW%GREENLEE%'),('%GRAGERT%'),('JULIE%FORSYTHE%'),('%SKYLES%'),('%STUEBS%'),('%QUAYE%'),('NILE%PORTER%'),('%LAMERS%'),('%EYLER%'),('%FOTIS%'),('%MAGILL%'),('DAN%CURRAN%')),
p AS (SELECT EIN, ORGANIZATION_NAME org, UPPER(CUSTODIAN_NAME) who, 'custodian' role FROM LIBRARY_MARTS.POLITICS.POLITICS__IRS527_8872_REPORTS
  UNION SELECT EIN, ORGANIZATION_NAME, UPPER(CONTACT_NAME), 'contact' FROM LIBRARY_MARTS.POLITICS.POLITICS__IRS527_8872_REPORTS
  UNION SELECT EIN, ORGANIZATION_NAME, UPPER(CUSTODIAN_NAME), 'custodian8871' FROM LIBRARY_MARTS.POLITICS.POLITICS__IRS527_8871_ORGS
  UNION SELECT EIN, ORG_NAME, UPPER(ENTITY_NAME), 'officer' FROM LIBRARY_MARTS.POLITICS.POLITICS__IRS527_DIRECTORS_OFFICERS),
h AS (SELECT DISTINCT p.EIN, p.org, p.who, p.role FROM p JOIN nm ON p.who LIKE nm.pat),
s AS (SELECT EIN, ROUND(SUM(EXPENDITURE_AMOUNT)/1e6,2) raw_b_m, MIN(YEAR(EXPENDITURE_DATE)) y0, MAX(YEAR(EXPENDITURE_DATE)) y1 FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_B_EXPENDITURES WHERE EIN IN (SELECT EIN FROM h) GROUP BY 1)
SELECT h.EIN, MAX(h.org) org, LISTAGG(DISTINCT h.who||' ('||h.role||')', '; ') people, MAX(s.raw_b_m) raw_b_m, MAX(s.y0) y0, MAX(s.y1) y1,
  IFF(h.EIN IN ('821194581','822366231','815214552','843153271','822315009','834686848','843763411','853307234','472041040','273594732','843763242','921706849','922354897','861386683','843763606','922452599','923489519','854325630','923489713'),'Y','N') in19
FROM h LEFT JOIN s USING (EIN) GROUP BY h.EIN ORDER BY in19, raw_b_m DESC NULLS LAST

-- Q23 bmf_people
-- tax-exempt orgs "in care of" the 19's custodians/officers or the FEC twins' treasurers (IRS master file IN_CARE_OF, distinctive names), plus Pub 78 deductibility for any hit
WITH nm AS (SELECT column1 pat FROM VALUES ('%PLISHKA%'),('%DATWYLER%'),('%RICHARD%LEAGUE%'),('%KEVITT%'),('%STEFANIDES%'),('%CAPPLEMAN%'),('%MCGRAIN%'),
  ('%PULCIANI%'),('%NIZICK%'),('%MATTHEW GREENLEE%'),('%GRAGERT%'),('%JULIE FORSYTHE%'),('%SKYLES%'),('%STUEBS%'),('%QUAYE%'),('%NILE%PORTER%'),('%LAMERS%'),('%BERT%EYLER%'),('%FOTIS%'),('%MAGILL%'),('%DAN CURRAN%'),('%JUDITH%SECHER%'),('%MAJCEN%'),('%MAICHLE%'),('%FRANKOVIS%')),
b AS (SELECT EIN, ORG_NAME, IN_CARE_OF, STREET, CITY, STATE, SUBSECTION_CODE, NTEE_CODE, RULING_DATE, REVENUE_AMT, ASSET_AMT, TAX_PERIOD_YYYYMM
  FROM LIBRARY_MARTS.CORPORATE_REGISTRY.CORPORATE_REGISTRY__FED_IRS_EO_BMF WHERE UPPER(IN_CARE_OF) LIKE ANY (SELECT pat FROM nm))
SELECT b.*, p.DEDUCTIBILITY_STATUS pub78 FROM b LEFT JOIN LIBRARY_MARTS.ECONOMICS.ECONOMICS__FED_IRS_PUB78_ELIGIBLE_DONEES p ON p.EIN = b.EIN
ORDER BY REVENUE_AMT DESC NULLS LAST

-- Q24 donor_sample
-- eyeball sample: 8 donors matched between the 19 (Schedule A) and Law Enforcement for a Safer America PAC (FEC), full names, city, occupation on both sides
WITH g AS (SELECT column1 EIN FROM VALUES ('821194581'),('822366231'),('815214552'),('843153271'),('822315009'),('834686848'),('843763411'),('853307234'),('472041040'),('273594732'),('843763242'),
  ('921706849'),('922354897'),('861386683'),('843763606'),('922452599'),('923489519'),('854325630'),('923489713')),
s AS (SELECT LEFT(CONTRIBUTOR_ZIP,5)||IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',1)), REGEXP_SUBSTR(TRIM(UPPER(CONTRIBUTOR_NAME)),'[A-Z]+$'))
   ||LEFT(IFF(CONTRIBUTOR_NAME LIKE '%,%', TRIM(SPLIT_PART(UPPER(CONTRIBUTOR_NAME),',',2)), TRIM(UPPER(CONTRIBUTOR_NAME))),1) kk,
   ANY_VALUE(CONTRIBUTOR_NAME) irs_name, ANY_VALUE(CONTRIBUTOR_CITY||' '||CONTRIBUTOR_STATE) irs_city, ANY_VALUE(CONTRIBUTOR_OCCUPATION) irs_occ, COUNT(DISTINCT EIN) n527, SUM(CONTRIBUTION_AMOUNT) irs_amt
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_IRS527_SCHEDULE_A_CONTRIBUTIONS WHERE EIN IN (SELECT EIN FROM g) GROUP BY 1),
f AS (SELECT LEFT(ZIP_CODE,5)||TRIM(SPLIT_PART(DONOR_NAME,',',1))||LEFT(TRIM(SPLIT_PART(DONOR_NAME,',',2)),1) kk, ANY_VALUE(DONOR_NAME) fec_name, ANY_VALUE(CITY||' '||STATE) fec_city, ANY_VALUE(OCCUPATION) fec_occ, SUM(TRANSACTION_AMT) fec_amt, COUNT(*) fec_gifts
  FROM LIBRARY_MARTS.FINANCE.FINANCE__FED_FEC_INDIV_CONTRIBUTIONS WHERE CMTE_ID='C00681825' AND COALESCE(MEMO_CD,'')<>'X' GROUP BY 1)
SELECT s.irs_name, f.fec_name, s.irs_city, f.fec_city, s.irs_occ, f.fec_occ, s.n527, s.irs_amt, f.fec_gifts, f.fec_amt FROM s JOIN f USING (kk) ORDER BY HASH(kk) LIMIT 8
